#!/usr/bin/env python3
"""Imports a weapon picture generated by PixelLab: python3 scripts/import_weapon.py KIND KEY IMAGE.png [options]

KIND is one of:
- weapon: a hand weapon lying flat, handle on the left, tip on the right. The tip is its rightmost pixel; the grip
  (where the fist closes, a = 0 in render_weapons.cpp) is found below the guard (the tallest column of the left
  half), or given with --grip X (fraction of the width, 0 = left end);
- icon: a power's icon (items, HUD);
- bow: a bow standing up, string on the left: its grip (the rightmost pixel around mid-height) and its two tips;
- shield: a shield seen from the front: its centre and radius.
Options: --flip (mirror the picture first), --grip X, --axis Y (row of the weapon's axis, fraction of the height).

Writes assets/sprites/weapon_KEY.png (cropped, paletted) and its line in assets/sprites/sheets.txt.
"""
import argparse
import os

import numpy as np
from PIL import Image


def paletted(img):
    arr = np.asarray(img)
    opaque = arr[..., 3] > 0
    cols = np.unique(arr[opaque][:, :3], axis=0)
    if len(cols) > 255:
        return img
    key = (arr[..., 0].astype(np.uint32) << 16) | (arr[..., 1].astype(np.uint32) << 8) | arr[..., 2]
    keys = (cols[:, 0].astype(np.uint32) << 16) | (cols[:, 1].astype(np.uint32) << 8) | cols[:, 2]
    idx = (np.searchsorted(keys, key) + 1).astype(np.uint8)
    idx[~opaque] = 0
    p = Image.fromarray(idx, "P")
    pal = [0, 0, 0] + [int(v) for c in cols for v in c]
    p.putpalette(pal + [0] * (768 - len(pal)))
    return p


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("kind", choices=["weapon", "icon", "bow", "shield"])
    ap.add_argument("key")
    ap.add_argument("image")
    ap.add_argument("--flip", action="store_true")
    ap.add_argument("--grip", type=float, default=None)
    ap.add_argument("--axis", type=float, default=None)
    a = ap.parse_args()

    img = Image.open(a.image).convert("RGBA")
    if a.flip:
        img = img.transpose(Image.Transpose.FLIP_LEFT_RIGHT)
    alpha = np.asarray(img)[..., 3]
    img.putalpha(Image.fromarray(np.where(alpha >= 128, 255, 0).astype(np.uint8)))
    img = img.crop(img.getbbox())
    w, h = img.size
    m = np.asarray(img)[..., 3] > 0
    if a.kind == "weapon":
        cols = m.sum(axis=0)
        if a.grip is not None:
            gx = a.grip * (w - 1)
        else:
            half = max(2, int(w * 0.45))
            guard = int(np.argmax(cols[:half]))
            gx = guard - 0.4 * guard if guard > w * 0.08 else w * 0.22
        ys = np.nonzero(m[:, int(round(gx))])[0]
        gy = a.axis * (h - 1) if a.axis is not None else (float(ys.mean()) if len(ys) else h / 2)
        tx = float(np.nonzero(cols)[0].max())
        vals = [gx, gy, tx, gy]
    elif a.kind == "icon":
        vals = []
    elif a.kind == "bow":
        rows = np.nonzero(m.any(axis=1))[0]
        mid = (rows.min() + rows.max()) / 2
        band = m[int(mid - h * 0.1):int(mid + h * 0.1) + 1]
        hx = float(np.nonzero(band.any(axis=0))[0].max())
        top, bottom = rows.min(), rows.max()
        ux = float(np.nonzero(m[top])[0].mean())
        dx = float(np.nonzero(m[bottom])[0].mean())
        vals = [hx, float(mid), ux, float(top), dx, float(bottom)]
    else:
        vals = [w / 2, h / 2, max(w, h) / 2]
    root = os.path.normpath(os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
    out = os.path.join(root, "assets", "sprites", f"weapon_{a.key}.png")
    p = paletted(img)
    if p.mode == "P":
        p.save(out, optimize=True, transparency=0)
    else:
        p.save(out, optimize=True)
    index = os.path.join(root, "assets", "sprites", "sheets.txt")
    lines = open(index).read().splitlines() if os.path.exists(index) else []
    header = [l for l in lines if l.startswith("#")]
    body = [l for l in lines if l.strip() and not l.startswith("#") and not l.split()[:2] == [a.kind, a.key]]
    body.append(" ".join([a.kind, a.key, str(w), str(h)] + [f"{v:.1f}" for v in vals]))
    open(index, "w").write("\n".join(header + sorted(body)) + "\n")
    print(a.kind, a.key, w, h, *[f"{v:.1f}" for v in vals])


if __name__ == "__main__":
    main()
